```apex
public with sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    private static final String ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Pattern CODE_PATTERN = Pattern.compile('^[A-Z]{3}$');

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // Validate and normalise the base currency.
        String normalisedBase = normaliseCode(baseCurrency);
        if (normalisedBase == null) {
            throw new ExchangeRateException('Invalid base currency code: ' + baseCurrency);
        }

        // Validate the quote set.
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currency set must not be null or empty.');
        }

        // Normalise every quote code (preserving order of discovery for determinism).
        Set<String> normalisedQuotes = new Set<String>();
        for (String raw : quoteCurrencies) {
            String normalised = normaliseCode(raw);
            if (normalised == null) {
                throw new ExchangeRateException('Invalid quote currency code: ' + raw);
            }
            normalisedQuotes.add(normalised);
        }

        // Build the request.
        String symbols = String.join(new List<String>(normalisedQuotes), ',');
        String url = ENDPOINT
            + '?base=' + EncodingUtil.urlEncode(normalisedBase, 'UTF-8')
            + '&symbols=' + EncodingUtil.urlEncode(symbols, 'UTF-8');

        HttpRequest req = new HttpRequest();
        req.setEndpoint(url);
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');

        Http http = new Http();
        HttpResponse res = http.send(req);

        // Retry once on 503 with an identical request.
        if (res.getStatusCode() == 503) {
            res = http.send(req);
        }

        if (res.getStatusCode() != 200) {
            throw new ExchangeRateException(
                'Exchange rate callout failed with HTTP status ' + res.getStatusCode());
        }

        // Parse the body.
        Map<String, Object> parsed;
        try {
            parsed = (Map<String, Object>) JSON.deserializeUntyped(res.getBody());
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse exchange rate response: ' + e.getMessage());
        }

        if (parsed == null || !(parsed.get('rates') instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Exchange rate response did not contain a valid rates object.');
        }

        Map<String, Object> rates = (Map<String, Object>) parsed.get('rates');

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String code : normalisedQuotes) {
            if (!rates.containsKey(code) || rates.get(code) == null) {
                throw new ExchangeRateException('No rate returned for requested currency: ' + code);
            }
            try {
                result.put(code, Decimal.valueOf(String.valueOf(rates.get(code))));
            } catch (Exception e) {
                throw new ExchangeRateException('Invalid rate value for currency ' + code + ': ' + e.getMessage());
            }
        }

        return result;
    }

    /**
     * Trims and upper-cases the supplied code and returns it only if it is exactly
     * three letters A-Z. Returns null for any invalid input.
     */
    private static String normaliseCode(String code) {
        if (code == null) {
            return null;
        }
        String normalised = code.trim().toUpperCase();
        if (!CODE_PATTERN.matcher(normalised).matches()) {
            return null;
        }
        return normalised;
    }
}
