```apex
public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // Validate maxRows
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // Validate object name
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name is required.');
        }

        Schema.SObjectType sobjType = Schema.getGlobalDescribe().get(objectApiName.toLowerCase());
        if (sobjType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }

        Schema.DescribeSObjectResult objDescribe = sobjType.getDescribe();

        // Object-level read security
        if (!objDescribe.isAccessible()) {
            throw new SearchException('You do not have access to object: ' + objDescribe.getName());
        }

        // Validate fields list
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }

        // Map of lowercase field name -> field describe
        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

        // Build SELECT clause, always including Id
        List<String> selectFields = new List<String>{ 'Id' };
        Set<String> selectAdded = new Set<String>{ 'id' };

        for (String f : fields) {
            if (String.isBlank(f)) {
                throw new SearchException('Field name cannot be blank.');
            }
            Schema.SObjectField token = resolveField(fieldMap, f, objDescribe.getName());
            Schema.DescribeFieldResult dfr = token.getDescribe();

            if (!dfr.isAccessible()) {
                throw new SearchException('You do not have access to field: ' + dfr.getName());
            }

            String canonical = dfr.getName();
            if (!selectAdded.contains(canonical.toLowerCase())) {
                selectFields.add(canonical);
                selectAdded.add(canonical.toLowerCase());
            }
        }

        // Build WHERE clause with bind variables
        List<String> whereClauses = new List<String>();
        // bindMap: binding name -> value
        Map<String, Object> bindMap = new Map<String, Object>();
        Integer bindCounter = 0;

        if (filters != null && !filters.isEmpty()) {
            for (String filterField : filters.keySet()) {
                if (String.isBlank(filterField)) {
                    throw new SearchException('Filter field name cannot be blank.');
                }
                Schema.SObjectField token = resolveField(fieldMap, filterField, objDescribe.getName());
                Schema.DescribeFieldResult dfr = token.getDescribe();

                if (!dfr.isAccessible()) {
                    throw new SearchException('You do not have access to field: ' + dfr.getName());
                }
                if (!dfr.isFilterable()) {
                    throw new SearchException('Field cannot be filtered: ' + dfr.getName());
                }

                String bindName = 'bind' + bindCounter;
                bindCounter++;
                bindMap.put(bindName, filters.get(filterField));
                whereClauses.add(dfr.getName() + ' = :' + bindName);
            }
        }

        // Validate ORDER BY field
        String orderByCanonical = null;
        if (String.isNotBlank(orderByField)) {
            Schema.SObjectField token = resolveField(fieldMap, orderByField, objDescribe.getName());
            Schema.DescribeFieldResult dfr = token.getDescribe();

            if (!dfr.isAccessible()) {
                throw new SearchException('You do not have access to field: ' + dfr.getName());
            }
            if (!dfr.isSortable()) {
                throw new SearchException('Field cannot be sorted: ' + dfr.getName());
            }
            orderByCanonical = dfr.getName();
        }

        // Assemble the SOQL query
        String query = 'SELECT ' + String.join(selectFields, ', ')
            + ' FROM ' + objDescribe.getName();

        if (!whereClauses.isEmpty()) {
            query += ' WHERE ' + String.join(whereClauses, ' AND ');
        }

        if (orderByCanonical != null) {
            query += ' ORDER BY ' + orderByCanonical + ' ASC';
        }

        // Bind the limit as well
        bindMap.put('maxRowsBind', maxRows);
        query += ' LIMIT :maxRowsBind';

        try {
            return Database.queryWithBinds(query, bindMap, AccessLevel.USER_MODE);
        } catch (Exception e) {
            throw new SearchException(e.getMessage());
        }
    }

    private static Schema.SObjectField resolveField(
        Map<String, Schema.SObjectField> fieldMap,
        String fieldName,
        String objectName
    ) {
        Schema.SObjectField token = fieldMap.get(fieldName.toLowerCase());
        if (token == null) {
            throw new SearchException(
                'Field "' + fieldName + '" is not a field of object ' + objectName + '.'
            );
        }
        return token;
    }
}
