public with sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;

        public Order() {
            this.lines = new List<Line>();
            this.total = 0;
        }
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static OrderPayloadParser.Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body is null or blank');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Body is not valid JSON');
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Body is not a JSON object');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        Order order = new Order();

        // number
        Object numberVal = root.get('number');
        String orderNumber = (numberVal == null) ? null : String.valueOf(numberVal);
        if (String.isBlank(orderNumber)) {
            throw new PayloadException('Missing or blank number');
        }
        order.orderNumber = orderNumber;

        // date
        Object dateVal = root.get('date');
        if (dateVal != null && String.isNotBlank(String.valueOf(dateVal))) {
            String dateStr = String.valueOf(dateVal);
            try {
                List<String> parts = dateStr.split('-');
                if (parts.size() != 3) {
                    throw new PayloadException('Invalid date');
                }
                order.orderDate = Date.newInstance(
                    Integer.valueOf(parts[0]),
                    Integer.valueOf(parts[1]),
                    Integer.valueOf(parts[2])
                );
            } catch (PayloadException pe) {
                throw pe;
            } catch (Exception e) {
                throw new PayloadException('Invalid date: ' + dateStr);
            }
        }

        // currency
        Object currencyVal = root.get('currency');
        if (currencyVal != null) {
            order.currencyCode = String.valueOf(currencyVal);
        }

        // customer
        Object customerVal = root.get('customer');
        if (customerVal != null) {
            if (!(customerVal instanceof Map<String, Object>)) {
                throw new PayloadException('customer is not a JSON object');
            }
            Map<String, Object> customer = (Map<String, Object>) customerVal;
            Object emailVal = customer.get('email');
            if (emailVal != null) {
                order.customerEmail = String.valueOf(emailVal);
            }
        }

        // lines
        Object linesVal = root.get('lines');
        Decimal total = 0;
        if (linesVal != null) {
            if (!(linesVal instanceof List<Object>)) {
                throw new PayloadException('lines is not a JSON array');
            }
            List<Object> rawLines = (List<Object>) linesVal;
            for (Object rawLine : rawLines) {
                if (!(rawLine instanceof Map<String, Object>)) {
                    throw new PayloadException('line is not a JSON object');
                }
                Map<String, Object> lineMap = (Map<String, Object>) rawLine;
                Line line = parseLine(lineMap);
                order.lines.add(line);
                total = total + line.lineTotal;
            }
        }

        order.total = total;

        return order;
    }

    private static Line parseLine(Map<String, Object> lineMap) {
        Line line = new Line();

        // sku
        Object skuVal = lineMap.get('sku');
        String sku = (skuVal == null) ? null : String.valueOf(skuVal);
        if (String.isBlank(sku)) {
            throw new PayloadException('Missing sku on line');
        }
        line.sku = sku;

        // quantity
        Object qtyVal = lineMap.get('quantity');
        if (qtyVal == null) {
            throw new PayloadException('Missing quantity on line');
        }
        Integer quantity;
        try {
            quantity = toDecimal(qtyVal).intValue();
        } catch (Exception e) {
            throw new PayloadException('Invalid quantity on line');
        }
        if (quantity <= 0) {
            throw new PayloadException('Non-positive quantity on line');
        }
        line.quantity = quantity;

        // unitPrice
        Object priceVal = lineMap.get('unitPrice');
        if (priceVal == null) {
            throw new PayloadException('Missing unitPrice on line');
        }
        Decimal unitPrice;
        try {
            unitPrice = toDecimal(priceVal);
        } catch (Exception e) {
            throw new PayloadException('Invalid unitPrice on line');
        }
        if (unitPrice < 0) {
            throw new PayloadException('Negative unitPrice on line');
        }
        line.unitPrice = unitPrice;

        // discount
        Object discountVal = lineMap.get('discount');
        Decimal discount = 0;
        if (discountVal != null) {
            try {
                discount = toDecimal(discountVal);
            } catch (Exception e) {
                throw new PayloadException('Invalid discount on line');
            }
        }
        line.discount = discount;

        // lineTotal
        Decimal raw = (Decimal) quantity * unitPrice * (1 - discount);
        line.lineTotal = raw.setScale(2, System.RoundingMode.HALF_UP);

        return line;
    }

    private static Decimal toDecimal(Object value) {
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return (Decimal) ((Integer) value);
        }
        if (value instanceof Long) {
            return (Decimal) ((Long) value);
        }
        if (value instanceof Double) {
            return Decimal.valueOf((Double) value);
        }
        return Decimal.valueOf(String.valueOf(value));
    }

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        JSONGenerator gen = JSON.createGenerator(false);
        gen.writeStartObject();
        gen.writeStringField('number', order.orderNumber);
        gen.writeStringField('status', 'RECEIVED');
        gen.writeNumberField('lineCount', order.lines == null ? 0 : order.lines.size());
        gen.writeNumberField('total', order.total == null ? 0 : order.total);
        gen.writeEndObject();
        return gen.getAsString();
    }
}
