public with sharing class ErpAccountSyncJob implements Queueable {

    private Set<Id> accountIds;
    private Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the transaction finalizer before doing any work.
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        List<Account> accounts = new List<Account>();
        for (Id accId : accountIds) {
            accounts.add(new Account(Id = accId, Description = 'Synced to ERP'));
        }

        // All-or-nothing save; do not catch so a failure fails the job
        // and rolls back all its changes.
        update accounts;
    }
