public with sharing class LogPurgeJob implements Schedulable {

    // No-argument constructor
    public LogPurgeJob() {}

    public void execute(SchedulableContext sc) {
        purge();
    }

    /**
     * Deletes FB_Integration_Log__c records that are past their retention window:
     *  - ERROR logs are kept until they were created more than 180 days ago.
     *  - All other logs (including blank Level__c) are deleted once created more than 30 days ago.
     */
    public static void purge() {
        Datetime cutoffStandard = Datetime.now().addDays(-30);
        Datetime cutoffError = Datetime.now().addDays(-180);

        List<FB_Integration_Log__c> toDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (Level__c = 'ERROR' AND CreatedDate < :cutoffError)
               OR ((Level__c != 'ERROR' OR Level__c = null) AND CreatedDate < :cutoffStandard)
            WITH SYSTEM_MODE
        ];

        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
    }

    /**
     * Schedules this job to run every day at 02:00 under the job name 'Log purge (nightly)'.
     * @return the Id returned by System.schedule.
     */
    public static Id scheduleNightly() {
        // Seconds Minutes Hours Day-of-month Month Day-of-week Year
        String cron = '0 0 2 * * ?';
        return System.schedule('Log purge (nightly)', cron, new LogPurgeJob());
    }
}
