public with sharing class OpportunityWinService {

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        Integer closedCount = 0;
        Date today = Date.today();

        for (Opportunity opp : opportunities) {
            if (opp.StageName == 'Closed Won') {
                continue;
            }

            opp.StageName = 'Closed Won';
            opp.CloseDate = today;
            uow.registerDirty(opp);

            Deal_Won__e event = new Deal_Won__e(
                Opportunity_Id__c = opp.Id,
                Amount__c = opp.Amount
            );
            // Only published after the DML in this unit of work commits successfully.
            uow.registerPublishAfterSuccessTransaction(event);

            closedCount++;
        }

        // A single commit: opportunity updates are committed first; the events are
        // published only after that DML succeeds. If the save fails, the exception
        // propagates and no Deal_Won__e is published.
        uow.commitWork();

        return closedCount;
    }
}
