    for (Case c : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(c.Id);
        // Only act on the transition from not-closed to closed.
        if (c.IsClosed && !oldCase.IsClosed) {
            newlyClosedCaseIds.add(c.Id);
        }
    }

    if (!newlyClosedCaseIds.isEmpty()) {
        System.enqueueJob(new CaseSurveyJob(newlyClosedCaseIds));
    }
