/**
 * Asynchronously creates CSAT survey follow-up Tasks for closed Cases.
 *
 * Runs as a Queueable so the survey step can grow (a vendor callout is planned;
 * Queueable supports chaining and, with Database.AllowsCallouts, HTTP callouts).
 *
 * Only Ids are passed across the async boundary and the records are re-queried
 * here, which avoids serializing full sObjects and guards against stale state.
 */
public with sharing class CaseSurveyJob implements Queueable {

    private final Set<Id> caseIds;

    public CaseSurveyJob(Set<Id> caseIds) {
        this.caseIds = caseIds == null ? new Set<Id>() : caseIds;
    }

    // Convenience constructor so a single Id can still be enqueued if desired.
    public CaseSurveyJob(Id caseId) {
        this(new Set<Id>{ caseId });
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId, IsClosed
            FROM Case
            WHERE Id IN :caseIds
            WITH SECURITY_ENFORCED
        ];

        Date dueDate = Date.today().addDays(2);
        List<Task> tasks = new List<Task>();

        for (Case c : cases) {
            // Cases without a contact get no task.
            // Re-check IsClosed in case it was reopened between the trigger and now.
            if (c.ContactId == null || !c.IsClosed) {
                continue;
            }

            tasks.add(new Task(
                WhatId       = c.Id,
                WhoId        = c.ContactId,
                Subject      = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = dueDate,
                Status       = 'Not Started'
            ));
        }

        if (!tasks.isEmpty()) {
            // Partial success: a single bad row (e.g. validation) does not block
            // the rest, honouring "one failure can't affect the others".
            Database.insert(tasks, false);
        }
    }
