public with sharing class RenewalReminderService {

    /**
     * Sends a renewal reminder email to the owner of each supplied opportunity.
     *
     * @param opportunityIds up to 200 opportunity Ids (one scheduled batch)
     * @return the number of emails that were sent successfully
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Query once, in bulk, outside the loop.
        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
            WITH USER_MODE
        ];

        Integer sentCount = 0;

        for (Opportunity opp : opportunities) {
            try {
                Messaging.SingleEmailMessage msg = new Messaging.SingleEmailMessage();
                msg.setTargetObjectId(opp.OwnerId);
                msg.setSaveAsActivity(false);
                msg.setSubject('Renewal due: ' + opp.Name);
                msg.setPlainTextBody(
                    'The opportunity "' + opp.Name + '" is due for renewal. ' +
                    'Its close date is ' + String.valueOf(opp.CloseDate) + '.'
                );

                // One send call per opportunity so a single failure does not
                // block the remaining reminders.
                Messaging.SendEmailResult[] results =
                    Messaging.sendEmail(new List<Messaging.SingleEmailMessage>{ msg });

                if (results != null && !results.isEmpty() && results[0].isSuccess()) {
                    sentCount++;
                }
            } catch (Exception e) {
                // Swallow the failure for this one email and keep going.
                System.debug(LoggingLevel.ERROR,
                    'Renewal reminder failed for Opportunity ' + opp.Id + ': ' + e.getMessage());
            }
        }

        return sentCount;
    }
}
