```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY = 300;
const MIN_CHARS = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    error;

    // Timer id for the debounce window.
    _debounceTimeout;
    // Monotonically increasing request id; only the latest response wins.
    _requestId = 0;
    // Guard against updating state after the component is disconnected.
    _isConnected = true;

    disconnectedCallback() {
        this._isConnected = false;
        // Cancel any pending debounced search so it never runs after removal.
        clearTimeout(this._debounceTimeout);
    }

    handleChange(event) {
        const searchTerm = (event.target.value || '').trim();

        // Always cancel any pending search; we either reschedule or abort.
        clearTimeout(this._debounceTimeout);

        if (searchTerm.length < MIN_CHARS) {
            // Below threshold: do not call Apex, clear results.
            // Invalidate in-flight requests so late responses are ignored.
            this._requestId += 1;
            this.contacts = [];
            this.error = undefined;
            return;
        }

        this._debounceTimeout = setTimeout(() => {
            this.runSearch(searchTerm);
        }, DEBOUNCE_DELAY);
    }

    runSearch(searchTerm) {
        if (!this._isConnected) {
            return;
        }

        const requestId = ++this._requestId;

        searchContacts({ searchTerm })
            .then((result) => {
                // Ignore if disconnected or a newer request has started.
                if (!this._isConnected || requestId !== this._requestId) {
                    return;
                }
                this.contacts = result;
                this.error = undefined;
            })
            .catch((error) => {
                if (!this._isConnected || requestId !== this._requestId) {
                    return;
                }
                this.contacts = [];
                this.error = error;
            });
    }

    get errorMessage() {
        return this.error && this.error.body
            ? this.error.body.message
            : '';
    }
}
