import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    /** Array of { key, productName, quantity } */
    @api lines;

    showError = false;

    get editors() {
        return Array.from(
            this.template.querySelectorAll('c-line-item-editor')
        );
    }

    handleReset() {
        this.editors.forEach((editor) => editor.reset());
        this.showError = false;
    }

    handleSubmit() {
        const editors = this.editors;

        // Validate every editor, even after one is invalid, so that
        // all invalid lines display their errors at once.
        let allValid = true;
        editors.forEach((editor) => {
            const isValid = editor.validate();
            if (!isValid) {
                allValid = false;
            }
        });

        if (allValid) {
            this.showError = false;
            const lines = editors.map((editor) => editor.getValue());
            this.dispatchEvent(
                new CustomEvent('submit', {
                    detail: { lines }
                })
            );
        } else {
            this.showError = true;
        }
    }
}
