        return Array.from(this.template.querySelectorAll('lightning-input[data-field]'));
    }

    getEmailInput() {
        return this.template.querySelector('lightning-input[data-field="email"]');
    }

    validateWorkEmail() {
        const emailInput = this.getEmailInput();
        const domain = (this.email || '').split('@')[1];
        const normalizedDomain = domain ? domain.toLowerCase() : '';
        if (BLOCKED_DOMAINS.includes(normalizedDomain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }
    }

