```javascript
import { LightningElement, api, track } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value = '';
    _activeIndex = 0;

    @track _renderedOptions = [];

    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = Array.isArray(val) ? val : [];
        this.syncActiveToValue();
        this.buildOptions();
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val == null ? '' : val;
        this.syncActiveToValue();
        this.buildOptions();
    }

    get listboxId() {
        return 'status-listbox';
    }

    get activeDescendant() {
        const active = this._renderedOptions[this._activeIndex];
        return active ? active.id : null;
    }

    optionId(index) {
        return `${this.listboxId}-option-${index}`;
    }

    // Move the active option to the currently selected option (or first option
    // when nothing is selected / the value is not found).
    syncActiveToValue() {
        if (!this._options.length) {
            this._activeIndex = 0;
            return;
        }
        const idx = this._options.findIndex((o) => o.value === this._value);
        this._activeIndex = idx === -1 ? 0 : idx;
    }

    buildOptions() {
        this._renderedOptions = this._options.map((o, index) => ({
            key: this.optionId(index),
            id: this.optionId(index),
            value: o.value,
            label: o.label,
            ariaSelected: o.value === this._value ? 'true' : 'false'
        }));
    }

    handleKeydown(event) {
        const lastIndex = this._options.length - 1;
        if (lastIndex < 0) {
            return;
        }

        switch (event.key) {
            case 'ArrowDown':
                event.preventDefault();
                this.setActiveIndex(Math.min(this._activeIndex + 1, lastIndex));
                break;
            case 'ArrowUp':
                event.preventDefault();
                this.setActiveIndex(Math.max(this._activeIndex - 1, 0));
                break;
            case 'Home':
                event.preventDefault();
                this.setActiveIndex(0);
                break;
            case 'End':
                event.preventDefault();
                this.setActiveIndex(lastIndex);
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                this.selectIndex(this._activeIndex);
                break;
            default:
                // Every other key (notably Tab) keeps its default behaviour.
                break;
        }
    }

    handleOptionClick(event) {
        const clickedValue = event.currentTarget.dataset.value;
        const index = this._options.findIndex((o) => o.value === clickedValue);
        if (index !== -1) {
            this.setActiveIndex(index);
            this.selectIndex(index);
        }
    }

    setActiveIndex(index) {
        this._activeIndex = index;
    }

    selectIndex(index) {
        const option = this._options[index];
        if (!option) {
            return;
        }
        if (option.value === this._value) {
            // Already selected: dispatch nothing.
            return;
        }
        this._value = option.value;
        this.buildOptions();
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value }
            })
        );
    }
}
