/**
 * TDTM trigger handler that creates a follow-up Task when an Opportunity
 * becomes a qualifying major gift (Closed Won with Amount >= 5000).
 *
 * Registered via an NPSP Trigger Handler record:
 *   Class          = OPP_MajorGiftFollowUp_TDTM
 *   Object         = Opportunity
 *   Trigger Action = AfterInsert;AfterUpdate
 *   Load Order     = 5
 *   Asynchronous   = false
 *
 * No Apex trigger is defined; NPSP's TDTM dispatcher invokes run(). The handler
 * stops firing when the admin deactivates the Trigger Handler record.
 */
global without sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    // Major gift threshold.
    private static final Decimal MAJOR_GIFT_AMOUNT = 5000;

    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        // Build a map of old-state records for quick lookup on update.
        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>();
        if (oldlist != null) {
            for (SObject so : oldlist) {
                Opportunity oldOpp = (Opportunity) so;
                oldMap.put(oldOpp.Id, oldOpp);
            }
        }

        Boolean isInsert = (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert);
        Boolean isUpdate = (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate);

        if (!isInsert && !isUpdate) {
            return dmlWrapper;
        }

        List<Task> tasksToCreate = new List<Task>();

        for (SObject so : newlist) {
            Opportunity opp = (Opportunity) so;

            Boolean qualifiesNow = qualifies(opp);
            if (!qualifiesNow) {
                continue;
            }

            if (isUpdate) {
                // Only fire when it was NOT qualifying before.
                Opportunity oldOpp = oldMap.get(opp.Id);
                if (oldOpp != null && qualifies(oldOpp)) {
                    continue;
                }
            }

            tasksToCreate.add(buildTask(opp));
        }

        if (!tasksToCreate.isEmpty()) {
            // Hand tasks to the dispatcher so all TDTM DML is batched together.
            dmlWrapper.objectsToInsert.addAll((List<SObject>) tasksToCreate);
        }

        return dmlWrapper;
    }

    /**
     * An Opportunity qualifies as a major gift when it is Closed Won and its
     * Amount is at least the threshold.
     */
    private Boolean qualifies(Opportunity opp) {
        return opp.IsWon == true
            && opp.IsClosed == true
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_AMOUNT;
    }

    private Task buildTask(Opportunity opp) {
        Task t = new Task();
        t.Subject = 'Major gift thank-you call';
        t.Priority = 'High';
        t.Status = 'Not Started';
        t.WhatId = opp.Id;
        t.WhoId = opp.npsp__Primary_Contact__c;
        t.OwnerId = opp.OwnerId;
        t.ActivityDate = (opp.CloseDate != null) ? opp.CloseDate.addDays(3) : null;
        return t;
    }
}
```

**Notes on the implementation**

- **No SOQL, 1 DML:** The handler uses only fields already loaded on the trigger records (`IsWon`, `IsClosed`, `Amount`, `CloseDate`, `OwnerId`, `npsp__Primary_Contact__c`), so it issues **zero** of its own SOQL queries. All Task inserts are added to the `DmlWrapper`, which NPSP's dispatcher commits in a single batched DML — comfortably within limits for 200 records. (The task only required "at most 1 SOQL and 1 DML of its own"; using the DmlWrapper actually consumes none of the handler's own DML.)
- **No duplicate tasks on re-edit:** On update it compares the prior state via `oldlist`. If the Opportunity already qualified (Closed Won + Amount ≥ 5000) before the edit, no new Task is created. Insert fires only when it starts qualifying.
- **`IsWon`/`IsClosed`** are used rather than hard-coding the StageName `'Closed Won'`, which correctly reflects "Closed Won" across orgs/record types while remaining robust.
- **No Apex trigger** is defined, so the class runs purely through TDTM and stops the moment the admin deactivates the Trigger Handler record.

