public inherited sharing class TA_Opportunity_CollectForErpSync
    implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {
    // Accumulates across trigger chunks within a single DML operation.
    // Cleared by OpportunityErpSyncFinalizer at the end of the DML operation.
    @TestVisible
    private static Set<Id> idsToSync = new Set<Id>();

    public static Set<Id> getCollectedIds() {
        return idsToSync;
    }

    public static void reset() {
        idsToSync = new Set<Id>();
    }

    public void afterInsert(List<SObject> triggerNew) {
        for (SObject record : triggerNew) {
            Opportunity opp = (Opportunity) record;
            if (opp.Id != null) {
                idsToSync.add(opp.Id);
            }
        }
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldMap = new Map<Id, SObject>(triggerOld);
        for (SObject record : triggerNew) {
            Opportunity newOpp = (Opportunity) record;
            Opportunity oldOpp = (Opportunity) oldMap.get(newOpp.Id);
            if (oldOpp != null && newOpp.StageName != oldOpp.StageName) {
                idsToSync.add(newOpp.Id);
            }
        }
    }
}
