public inherited sharing class OpportunityErpSyncFinalizer implements TriggerAction.DmlFinalizer {
    public void execute(FinalizerHandler.Context context) {
        // This finalizer runs once at the end of every DML operation handled by the
        // framework, for every sObject. Only enqueue a job when this DML operation
        // actually collected Opportunity Ids that need syncing.
        Set<Id> idsToSync = TA_Opportunity_CollectForErpSync.getCollectedIds();
        try {
            if (idsToSync != null && !idsToSync.isEmpty()) {
                System.enqueueJob(new OpportunityErpSyncJob(idsToSync));
            }
        } finally {
            // Reset so a subsequent DML statement in the same transaction collects
            // and enqueues independently of this one.
            TA_Opportunity_CollectForErpSync.reset();
        }
    }
}
