        Id oppId = newOppId();
        Opportunity oldOpp = new Opportunity(Id = oppId, Amount = null);
        Opportunity newOpp = new Opportunity(Id = oppId, Amount = 1);

        Test.startTest();
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );
        Test.stopTest();

        System.assert(
            !newOpp.hasErrors(),
            'A record whose previous Amount was null should be accepted without error.'
        );
